// Deterministic comparison of the retained S15 and S20 measurement vectors.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
const read = (name) => JSON.parse(readFileSync(new URL(name, import.meta.url)));
const before = read('../s15/baseline-summary.json');
const after = read('./recheck-summary.json');
const f = (x, n = 1) => x == null ? '—' : x.toFixed(n);
const lines = [
  '# S15 → S20 comparison', '',
  '[DEMONSTRATED: retained `baseline-summary.json` and `recheck-summary.json`; generated by `tools/studies/s20/compare.mjs`.]', '',
  'CPU throttling is a proxy; GPU speed and unrelated host work are not controlled. Quantiles pool two 8-second trials per cell. Source/content changes and host variation are confounded: differences are observations, not isolated causal effects of the 3D conversion. The authored rock count also changes from 20 to 336 before the arrival-clear filter (world.ts at the recorded revisions).', '',
  '| Profile | Cache | Interaction median before → after (ms) | Largest before → after (ms) | Console-ready median before → after (ms) |',
  '| --- | --- | ---: | ---: | ---: |',
];
for (const a of after.loads) {
  const b = before.loads.find((r) => r.profile === a.profile && r.cache === a.cache);
  lines.push(`| ${a.profile} | ${a.cache} | ${f(b.firstInteraction.median)} → ${f(a.firstInteraction.median)} | ${f(b.firstInteraction.worst)} → ${f(a.firstInteraction.worst)} | ${f(b.consoleReady.median)} → ${f(a.consoleReady.median)} |`);
}
for (const profile of ['modest', 'native']) {
  lines.push('', `## ${profile} profile`, '',
    '| View | Warp | p95 before → after (ms) | Maximum before → after (ms) | Ship s/wall s before → after | Saturated % before → after |',
    '| --- | ---: | ---: | ---: | ---: | ---: |');
  for (const a of after.frames.filter((r) => r.profile === profile)) {
    const b = before.frames.find((r) => r.key === a.key);
    lines.push(`| ${a.view} | ${a.warp}× | ${f(b.p95)} → ${f(a.p95)} | ${f(b.worst)} → ${f(a.worst)} | ${f(b.shipPerWall)} → ${f(a.shipPerWall)} | ${f(b.saturationPercent)} → ${f(a.saturationPercent)} |`);
  }
}
const target = fileURLToPath(new URL('../../../docs/studies/s20/performance-comparison.md', import.meta.url));
writeFileSync(target, lines.join('\n') + '\n');
console.log('Wrote docs/studies/s20/performance-comparison.md');
